contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint depositAmt, uint minSum, uint am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        require(depositAmt >= minSum);
        require(depositAmt >= am);
        require(address(this).balance >= depositAmt);
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethBefore = address(c).balance;
        require(balBefore >= minSum && balBefore >= am);
        c.Collect(am); if (__ESBMC_reverted()) return;
        bool ok;
        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethAfter = address(c).balance;
        ok = (balBefore >= minSum && balBefore >= am);
        assert(ok && ethBefore == ethAfter + am && balAfter == balBefore - am);
    }
    receive() external payable {}
}

