pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 depositAmt, uint256 minSum, uint256 am) internal {
        depositAmt = bound(depositAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmt >= minSum);
        vm.assume(depositAmt >= am);
        vm.assume(address(this).balance >= depositAmt);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Deposit{value: depositAmt}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint ethBefore = address(c).balance;
        vm.assume(balBefore >= minSum && balBefore >= am);
        try c.Collect(am) {} catch { return; }
        bool ok;
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint ethAfter = address(c).balance;
        ok = (balBefore >= minSum && balBefore >= am);
        assertTrue(ok && ethBefore == ethAfter + am && balAfter == balBefore - am);
    }

    function testFuzz_run(uint256 depositAmt, uint256 minSum, uint256 am) public {
        _run(depositAmt, minSum, am);
    }

    receive() external payable {}
}
